function assessContractInternal(ws,contractId){
 const contract=contractAt(ws,contractId),analysis=analyseInternal(ws,contract.selectionId),issues=clone(analysis.issues),tables=[],crosswalks=[];
 const issue=(severity,code,message,context={})=>{const v={severity,code,message,...clone(context)};v.id='finding-'+hash(v).slice(0,40);issues.push(v);};
 const lookupMaps=new Map();
 for(const c of contract.crosswalks){const parsed=parseCsv(fileText(ws,c.fileId)),map=new Map(),rows=[];
  parsed.rows.forEach((cells,i)=>{const key=c.sourceKeyColumns.map(column=>column<cells.length?cells[column]:null),values=c.targetColumns.map(column=>column<cells.length?cells[column]:null),witness={fileId:c.fileId,record:i+2,headers:parsed.headers,cells};const row={key,values,witness};rows.push(row);const k=stable(key),group=map.get(k)||[];group.push(row);map.set(k,group);if(cells.length!==parsed.headers.length||key.some(v=>v===null||v==='')||values.some(v=>v===null))issue('error','CROSSWALK_ROW_INVALID','A full crosswalk row has absent/empty keys, missing output positions or different width.',{crosswalkId:c.id,witness});});
  for(const rows of map.values())if(rows.length>1){const same=new Set(rows.map(r=>stable(r.witness.cells))).size===1;issue(same?'warning':'error',same?'CROSSWALK_REPEATED':'CROSSWALK_CONFLICT','Every crosswalk witness is retained; different rows for one source key are ambiguous.',{crosswalkId:c.id,witnesses:rows.map(r=>r.witness)});}
  lookupMaps.set(c.id,map);crosswalks.push({...clone(c),rows});
 }
 function valueFor(selector,record,mapping,witness,tableId){
  const ref=selector.referenceId?record.references.find(r=>r.id===selector.referenceId):null;
  if(Object.hasOwn(selector,'constant'))return selector.constant;
  if(Object.hasOwn(selector,'field'))return record.fields[selector.field]??null;
  if(Object.hasOwn(selector,'column'))return selector.column<witness.effectiveCells.length?witness.effectiveCells[selector.column]:null;
  if(Object.hasOwn(selector,'crosswalkId')){const parts=ref?ref.parts:record.identity.parts;if(ref&&!ref.required&&parts.every(v=>v===null||v===''))return'';const group=lookupMaps.get(selector.crosswalkId)?.get(stable(parts));if(!group||new Set(group.map(r=>stable(r.witness.cells))).size!==1){issue('error','CROSSWALK_NOT_UNIQUE','The exact original record needs one unambiguous supplied crosswalk result.',{tableId,recordKey:record.key,crosswalkId:selector.crosswalkId,parts,witnesses:record.witnesses});return null;}return group[0].values[selector.index];}
  return(ref?ref.parts:record.identity.parts)[selector.keyIndex]??null;
 }
 for(const t of contract.tables){const mapping=mappingAt(ws,t.mappingId),rows=[],keyIndex=new Map();const selectedRecords=analysis.records.filter(r=>r.witnesses.some(w=>w.mappingId===mapping.id));
  for(const record of selectedRecords){const witness=record.witnesses.find(w=>w.mappingId===mapping.id),cells=t.headers.map((_,i)=>valueFor(t.columns[i],record,mapping,witness,t.id)),parts=t.keyColumns.map(column=>cells[column]),key=stable(parts),rowId='prepared-row-'+hash({tableId:t.id,sourceKey:record.key}).slice(0,40);
   const row={rowId,sourceKey:record.key,sourceIdentity:clone(record.identity),witnesses:clone(record.witnesses),key:parts,cells};rows.push(row);const list=keyIndex.get(key)||[];list.push(row);keyIndex.set(key,list);
   if(cells.some(v=>v===null)||parts.some(v=>v===null||v===''))issue('error','TARGET_VALUE_MISSING','A mapped output position or target key is absent; missing is not emitted as an empty success.',{tableId:t.id,rowId,sourceKey:record.key,cells,witnesses:record.witnesses});
   for(const ref of record.references)if(ref.parts.some(v=>v!==null&&v!=='')&&!t.referenceBindings.some(b=>b.referenceId===ref.id))issue('error','TARGET_RELATION_UNMAPPED','The selected original relationship has no explicit target key binding.',{tableId:t.id,rowId,referenceId:ref.id,sourceKey:record.key,witnesses:record.witnesses});
  }
  for(const group of keyIndex.values())if(group.length>1)issue('error','TARGET_KEY_CONFLICT','Multiple distinct source records map to the same destination key.',{tableId:t.id,key:group[0].key,rowIds:group.map(r=>r.rowId),sourceKeys:group.map(r=>r.sourceKey)});
  const csv=encodeCsv([t.headers,...rows.map(r=>r.cells)]);tables.push({id:t.id,mappingId:t.mappingId,headers:clone(t.headers),keyColumns:clone(t.keyColumns),rows,text:csv,...sha256Utf8(csv)});
 }
 const tablesById=new Map(tables.map(t=>[t.id,t])),recordsByKey=new Map(analysis.records.map(r=>[r.key,r]));
 for(const t of contract.tables){const output=tablesById.get(t.id);for(const binding of t.referenceBindings){const target=tablesById.get(binding.targetTableId),bySource=new Map(target.rows.map(r=>[r.sourceKey,r]));for(const row of output.rows){const record=recordsByKey.get(row.sourceKey),ref=record.references.find(r=>r.id===binding.referenceId),actual=binding.columns.map(c=>row.cells[c]);if(!ref.required&&ref.parts.every(v=>v===null||v==='')){if(actual.some(v=>v!==''))issue('error','TARGET_ABSENT_REFERENCE_DIFFERS','An absent optional source relationship was mapped to a nonempty target reference.',{tableId:t.id,rowId:row.rowId,referenceId:ref.id,actual});continue;}const targetRow=bySource.get(ref.targetKey);if(!targetRow||!equal(actual,targetRow.key))issue('error','TARGET_REFERENCE_MISMATCH','The explicit target foreign key does not match the output of its original referenced record.',{tableId:t.id,rowId:row.rowId,referenceId:ref.id,targetTableId:target.id,actual,expected:targetRow?.key??null});}}}
 const errors=issues.filter(i=>i.severity==='error').length;
 return{schema:'tjlabs.audit-target-assessment.v1',workspaceId:ws.id,revision:ws.revision,contractId,selectionId:contract.selectionId,basisSha256:analysis.basisSha256,stale:analysis.stale,ready:analysis.ready&&errors===0,authority:contract.authority,analysis,crosswalks,tables,issues,summary:{errors,warnings:issues.length-errors,tables:tables.length,rows:tables.reduce((n,t)=>n+t.rows.length,0)}};
}
export function assessContract(ws,{contractId}){validateWorkspace(ws);return assessContractInternal(ws,contractId);}
function compareReturn(ws,preparation,input){
 need(Array.isArray(input.tables)&&input.tables.length>0&&input.tables.length<=preparation.assessment.tables.length,'INVALID_RETURN','Select the actual complete returned files.');const seen=new Set(),tables=[],issues=[];
 const issue=(code,message,details={})=>issues.push({code,severity:'error',message,...clone(details)});
 for(const selected of input.tables){need(!seen.has(selected.tableId),'DUPLICATE_RETURN_TABLE','Select an original expected table once per return edition.');seen.add(selected.tableId);const expected=preparation.assessment.tables.find(t=>t.id===selected.tableId);need(expected,'RETURN_TABLE_UNSELECTED','Bind a table from the exact prepared edition.');const file=fileAt(ws,selected.fileId),parsed=parseCsv(utf8Text(decodeBase64(file.base64)));
  need(plain(selected.columns)&&Object.keys(selected.columns).length===expected.headers.length&&expected.headers.every((_,i)=>Object.hasOwn(selected.columns,String(i))),'INVALID_RETURN_MAPPING','Declare every expected column as an actual returned column or explicit null.');
  for(const value of Object.values(selected.columns))need(value===null||(Number.isInteger(value)&&value>=0&&value<parsed.headers.length),'INVALID_RETURN_MAPPING','Select actual returned column positions.');
  for(const c of expected.keyColumns)need(selected.columns[c]!==null,'RETURN_KEY_UNMAPPED','Bind every expected target key component to actual returned data.');
  const returned=parsed.rows.map((cells,i)=>{const values=expected.headers.map((_,j)=>{const column=selected.columns[j];return column===null?null:column<cells.length?cells[column]:null;});return{rowId:'return-row-'+hash({fileId:file.id,tableId:selected.tableId,record:i+2}).slice(0,40),record:i+2,cells:clone(cells),values,key:expected.keyColumns.map(c=>values[c])};});
  const original=new Map(expected.rows.map(r=>[stable(r.key),r])),actual=new Map();for(const row of returned){const key=stable(row.key),group=actual.get(key)||[];group.push(row);actual.set(key,group);if(row.cells.length!==parsed.headers.length||row.key.some(v=>v===null||v===''))issue('RETURN_ROW_INVALID','The original return has missing keys or a different row width.',{tableId:expected.id,rowId:row.rowId,record:row.record,expectedWidth:parsed.headers.length,observedWidth:row.cells.length});}
  const comparisons=[],counts={matched:0,changed:0,missing:0,unexpected:0,ambiguous:0,unconfirmed:0};
  for(const key of new Set([...original.keys(),...actual.keys()])){const before=original.get(key),group=actual.get(key)||[],after=group[0];let state;
   if(group.length>1){state='AMBIGUOUS';counts.ambiguous++;}else if(!before){state='UNEXPECTED';counts.unexpected++;}else if(!after){state='MISSING';counts.missing++;}else if(Object.values(selected.columns).some(v=>v===null)||after.values.some(v=>v===null)){state='UNCONFIRMED';counts.unconfirmed++;}else if(equal(before.cells,after.values)){state='MATCH';counts.matched++;}else{state='CHANGED';counts.changed++;}
   const cells=expected.headers.map((header,column)=>({column,header,expected:before?.cells[column]??null,actual:after?.values[column]??null,returnedColumn:selected.columns[column],equal:!!before&&!!after&&selected.columns[column]!==null&&after.values[column]!==null&&before.cells[column]===after.values[column]}));
   const row={state,key:before?.key??after.key,preparedRowId:before?.rowId??null,sourceKey:before?.sourceKey??null,sourceWitnesses:before?.witnesses??[],returnedRows:clone(group),cells};comparisons.push(row);if(state!=='MATCH')issue('RETURN_'+state,'The actual returned data has not matched this complete frozen prepared row.',{tableId:expected.id,...clone(row)});
  }
  tables.push({tableId:expected.id,fileId:file.id,originalHeaders:clone(parsed.headers),expectedHeaders:clone(expected.headers),columns:clone(selected.columns),rows:returned,comparisons,counts,bytes:file.bytes,sha256:file.sha256});
 }
 const unreported=preparation.assessment.tables.filter(t=>!seen.has(t.id)).map(t=>({tableId:t.id,preparedRows:t.rows.length,preparedRowIds:t.rows.map(r=>r.rowId)}));for(const t of unreported)issue('TABLE_UNREPORTED','No actual returned file is selected for this prepared table.',t);
 const counts=tables.reduce((sum,t)=>{for(const k of Object.keys(t.counts))sum[k]=(sum[k]||0)+t.counts[k];return sum;},{});
 return{schema:'tjlabs.audit-return-reconciliation.v1',preparationId:preparation.id,preparedSha256:preparation.outputSha256,tables,unreported,issues,ready:issues.length===0,nativeAcceptance:'UNCONFIRMED',permissionEnforcement:'NOT_ASSERTED',summary:{...counts,unreportedTables:unreported.length,errors:issues.length}};
}
export function saveContract(ws,input){return mutate(ws,'save-contract',input);}
export function prepareTarget(ws,input){return mutate(ws,'prepare-target',input);}
export function recordReturn(ws,input){return mutate(ws,'record-return',input);}
function applyTarget(ws,kind,input,revision,at){
 if(kind==='save-contract'){const contract=contractInput(ws,input,revision,at);ws.contracts.push(contract);return{contractId:contract.id,selectionId:contract.selectionId,tables:contract.tables.length};}
 if(kind==='prepare-target'){
  const contract=contractAt(ws,input.contractId),review=ws.reviews.find(r=>r.id===input.reviewId);need(review&&review.decision==='accepted'&&review.selectionId===contract.selectionId,'REVIEW_REQUIRED','Select the accepted review of this exact original source selection.');const assessment=assessContractInternal(ws,contract.id);need(assessment.ready,'TARGET_NOT_READY','Resolve the full actual target assessment before freezing prepared outputs.',{assessment});
  const outputSha256=hash(assessment.tables.map(t=>({id:t.id,headers:t.headers,keyColumns:t.keyColumns,rows:t.rows,bytes:t.bytes,sha256:t.sha256})));const prepared={...stamp(ws,input,revision,at,'preparation'),contractId:contract.id,reviewId:review.id,selectionId:contract.selectionId,note:text(input.note,'preparation note',16000),outputSha256,assessment};ws.preparations.push(prepared);return{preparationId:prepared.id,contractId:contract.id,outputSha256,tables:assessment.tables.length,rows:assessment.summary.rows};
 }
 if(kind==='record-return'){
  const prepared=preparationAt(ws,input.preparationId),comparison=compareReturn(ws,prepared,input);const received={...stamp(ws,input,revision,at,'return'),preparationId:prepared.id,submissionReference:text(input.submissionReference||'','actual submission reference',4000,true),note:text(input.note,'actual returned evidence note',16000),tableInputs:clone(input.tables),comparison};ws.returns.push(received);return{returnId:received.id,preparationId:prepared.id,ready:comparison.ready,summary:comparison.summary};
 }
 fail('UNKNOWN_OPERATION','The original operation kind is unsupported.');
}


export function inspectWorkspace(ws){validateWorkspace(ws);return{id:ws.id,title:ws.title,createdAt:ws.createdAt,revision:ws.revision,files:ws.files.map(({base64,...f})=>clone(f)),sources:clone(ws.sources),mappings:clone(ws.mappings),selections:clone(ws.selections),contracts:clone(ws.contracts),preparations:ws.preparations.map(({assessment,...p})=>({...clone(p),summary:clone(assessment.summary)})),returns:ws.returns.map(({comparison,...r})=>({...clone(r),summary:clone(comparison.summary),ready:comparison.ready})),reviews:ws.reviews.map(({report,...r})=>({...clone(r),summary:clone(report.summary)})),operations:clone(ws.operations)};}
const escapeHTML=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function htmlTable(headers,rows){return '<div class="table"><table><thead><tr>'+headers.map(h=>'<th>'+escapeHTML(h)+'</th>').join('')+'</tr></thead><tbody>'+rows.map(row=>'<tr>'+row.map(v=>'<td>'+escapeHTML(v===null?'[missing position]':typeof v==='object'?JSON.stringify(v):v)+'</td>').join('')+'</tr>').join('')+'</tbody></table></div>';}
function reportHTML(ws,report,extra={}){
 const section=(title,body)=>'<section><h2>'+escapeHTML(title)+'</h2>'+body+'</section>',json=v=>'<pre>'+escapeHTML(JSON.stringify(v,null,2))+'</pre>';
 let body='<h1>Audit Source Workspace</h1><p>'+escapeHTML(ws.title)+' · '+escapeHTML(ws.id)+' · revision '+ws.revision+'</p><p>Exact original records and source declarations. Structural readiness does not establish a supplier load, audit assurance or effective authorization.</p>';
 body+=section('Selected source and completeness',json({selectionId:report.selectionId,basisSha256:report.basisSha256,currentBasisSha256:report.currentBasisSha256,stale:report.stale,structurallyReady:report.structurallyReady,semanticAcceptance:report.semanticAcceptance,summary:report.summary,coverage:report.coverage}));
 body+=section('All findings',htmlTable(['Severity','Code','Message','Original context'],report.issues.map(i=>[i.severity,i.code,i.message,i])));
 for(const role of ROLE_NAMES){const r=report.roles[role];body+=section(role,htmlTable(['Compound identity','Fields','References','Complete original witnesses','Valid'],report.records.filter(v=>v.identity.role===role).map(v=>[v.identity,v.fields,v.references,v.witnesses,v.valid]))+json({declaration:r.declaration,counts:r.counts,coverage:r.coverage}));}
 body+=section('Complete graph',json(report.graph));body+=section('Document byte bindings',htmlTable(['Record','State','Expected original','Actual retained file'],report.documents.map(d=>[d.key,d.state,d.expected,d.actual])));
 body+=section('Permission and history basis',json({permissions:report.permissions.basis,history:report.history.basis,interpretation:report.permissions.interpretation}));
 if(extra.preparation){const p=extra.preparation;body+=section('Frozen prepared output',json({id:p.id,contractId:p.contractId,selectionId:p.selectionId,outputSha256:p.outputSha256,summary:p.assessment.summary})+p.assessment.tables.map(t=>'<h3>'+escapeHTML(t.id)+'</h3>'+htmlTable(['Prepared row ID','Original compound key','Target key',...t.headers],t.rows.map(r=>[r.rowId,r.sourceKey,r.key,...r.cells]))).join('')+'<details><summary>Complete prepared record and original witnesses</summary>'+json(p)+'</details>');}
 if(extra.returned){const r=extra.returned,c=r.comparison;body+=section('Actual complete returned comparison',json({id:r.id,preparationId:r.preparationId,submissionReference:r.submissionReference,ready:c.ready,nativeAcceptance:c.nativeAcceptance,permissionEnforcement:c.permissionEnforcement,summary:c.summary})+c.tables.map(t=>'<h3>'+escapeHTML(t.tableId)+'</h3>'+htmlTable(['Source file','Bytes','SHA-256','Counts'],[[t.fileId,t.bytes,t.sha256,t.counts]])+htmlTable(['State','Target key','Prepared row','Original source key','Returned records'],t.comparisons.map(x=>[x.state,x.key,x.preparedRowId,x.sourceKey,x.returnedRows.map(y=>y.record)]))+htmlTable(['State','Target key','Column','Heading','Expected','Actual','Returned column','Equal'],t.comparisons.flatMap(x=>x.cells.map(v=>[x.state,x.key,v.column,v.header,v.expected,v.actual,v.returnedColumn,v.equal])))+'<h4>Every original returned row and column</h4>'+htmlTable(['Original record','Row ID',...t.originalHeaders],t.rows.map(x=>[x.record,x.rowId,...x.cells]))).join('')+'<h3>Unreported tables</h3>'+htmlTable(['Table','Prepared records','Prepared row IDs'],c.unreported.map(t=>[t.tableId,t.preparedRows,t.preparedRowIds]))+'<details><summary>Complete original returned record, findings and witnesses</summary>'+json(r)+'</details>');}
 const selection=selectionAt(ws,report.selectionId);for(const mid of selection.mappingIds){const mapping=mappingAt(ws,mid),source=frozenRows(ws,mapping,selection);body+=section('Original and selected rows: '+source.source.filename,htmlTable(['Original record','Row ID','Original cells','Selected effective cells','Correction IDs'],source.rows.map(r=>[r.record,r.id,r.originalCells,r.cells,r.correctionIds||[]])));}
 body+=section('Full mapping, correction and operation history',json({mappings:ws.mappings,corrections:ws.corrections,selections:ws.selections,operations:ws.operations}));
 return '<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Audit source report</title><style>html{color-scheme:light}body{font:15px/1.5 system-ui,sans-serif;margin:0;background:#f5f5f5;color:#202020}main{max-width:1280px;margin:auto;padding:24px}h1,h2{line-height:1.2}h2{margin-top:0}section{background:#fff;border:1px solid #bdbdbd;padding:18px;margin:18px 0;break-inside:auto}.table{overflow:auto}table{border-collapse:collapse;width:100%}th,td{border:1px solid #bbb;text-align:left;vertical-align:top;padding:8px;overflow-wrap:anywhere}th{background:#eee}pre{white-space:pre-wrap;overflow-wrap:anywhere;font:12px/1.5 ui-monospace,monospace}a{color:#333}@media(max-width:600px){main{padding:10px}section{padding:10px}th,td{min-width:110px}}@media print{body{background:white}main{max-width:none;padding:0}section{border:0;padding:0}.table{overflow:visible}table{font-size:9px}th,td{min-width:0}pre{font-size:9px}}</style><main>'+body+'</main></html>\n';
}
export function renderReport(ws,{selectionId,preparationId,returnId}={}){validateWorkspace(ws);const chosen=selectionId||ws.selections.at(-1)?.id;need(chosen,'SELECTION_REQUIRED','Save an explicit original selection before rendering a complete report.');const report=analyseInternal(ws,chosen),preparation=preparationId?preparationAt(ws,preparationId):null,returned=returnId?ws.returns.find(r=>r.id===returnId):null;if(preparation)need(preparation.selectionId===chosen,'REPORT_SELECTION_MISMATCH','Keep the original prepared selection.');if(returnId){need(returned,'RETURN_NOT_FOUND','Select the original return.');need(preparationAt(ws,returned.preparationId).selectionId===chosen,'REPORT_SELECTION_MISMATCH','Keep the original returned selection.');}if(preparation&&returned)need(returned.preparationId===preparation.id,'REPORT_PREPARATION_MISMATCH','The shown return must belong to the exact shown prepared output.');return reportHTML(ws,report,{preparation,returned});}
export function buildHandover(ws){
 validateWorkspace(ws);const files=[];const addText=(path,type,text)=>files.push({path,type,text,...sha256Utf8(text)}),addBinary=(path,type,file)=>files.push({path,type,base64:file.base64,bytes:file.bytes,sha256:file.sha256});
 addText('workspace.json','application/json',exportWorkspace(ws));addText('history.json','application/json',JSON.stringify({schema:'tjlabs.audit-complete-history.v1',workspaceId:ws.id,operations:ws.operations,mappings:ws.mappings,corrections:ws.corrections,selections:ws.selections,reviews:ws.reviews,contracts:ws.contracts,preparations:ws.preparations,returns:ws.returns},null,2)+'\n');
 const originals=[];for(const f of ws.files){const ext=/\.([a-z0-9]{1,12})$/i.exec(f.filename)?.[1]?.toLowerCase()||'bin',path='originals/file-'+hash(f.id).slice(0,40)+'.'+ext;addBinary(path,f.mimeType,f);const {base64,...metadata}=f;originals.push({...metadata,path});}
 for(const s of ws.sources){const effective=effectiveSource(ws,s.id);addText('effective/source-'+hash(s.id).slice(0,40)+'.csv','text/csv',encodeCsv([effective.headers,...effective.rows.map(r=>r.cells)]));}
 for(const selection of ws.selections){const report=analyseInternal(ws,selection.id),name=hash(selection.id).slice(0,40);addText('selections/selection-'+name+'.json','application/json',JSON.stringify(report,null,2)+'\n');addText('selections/selection-'+name+'.html','text/html',reportHTML(ws,report));}
 for(const p of ws.preparations){const directory='prepared/preparation-'+hash(p.id).slice(0,40)+'/';addText(directory+'assessment.json','application/json',JSON.stringify(p,null,2)+'\n');for(const t of p.assessment.tables)addText(directory+'table-'+hash(t.id).slice(0,40)+'.csv','text/csv',t.text);}
 for(const r of ws.returns)addText('returns/return-'+hash(r.id).slice(0,40)+'.json','application/json',JSON.stringify(r,null,2)+'\n');
 const manifest={schema:'tjlabs.audit-complete-handover-manifest.v1',workspaceId:ws.id,title:ws.title,revision:ws.revision,originals,sourceRows:ws.sources.map(s=>({sourceId:s.id,fileId:s.fileId,role:s.role,side:s.side,headers:s.headers,rowCount:s.rowCount})),selections:ws.selections.map(s=>({id:s.id,basisSha256:s.basisSha256})),files:files.map(({text,base64,...f})=>f),meaning:'Complete original audit migration workspace and attributed history. Source ACLs are retained declarations, not local access rules. No vendor load, outcome or assurance judgment is inferred.'};
 addText('MANIFEST.json','application/json',JSON.stringify(manifest,null,2)+'\n');return{schema:'tjlabs.audit-complete-handover.v1',workspaceId:ws.id,revision:ws.revision,files,manifest};
}
